// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: a real depositor, distinct from c and the log contract.
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 10 ether);

        // The log file must be a contract that ACCEPTS the AddMessage call.
        LogAccept log = new LogAccept();
        vm.assume(actor != address(log));
        c.SetLogFile(address(log));

        // Drive a deposit from an arbitrary fuzzed actor.
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: with a functioning log file configured, ANY deposit from
        // ANY caller must succeed. The mutant stores msg.sender as the log, so a
        // caller whose code rejects the AddMessage call makes Put revert.
        assertTrue(ok);
    }
}

contract LogAccept {
    uint public count;

    function AddMessage(address, uint, string memory) external payable {
        count++;
    }

    fallback() external payable {}
    receive() external payable {}
}
